"""Write the auto-generated insights brief a PM would share with the team."""
from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from .trends import top_segment

if TYPE_CHECKING:
    from .pipeline import InsightsResult


def _pct(value: float) -> str:
    return f"{value:.0%}"


def _recommendation(row) -> str:
    growing = row.trend_significant and row.trend > 0
    if row.negative_rate < 0.2:
        return "Strength to protect and amplify in marketing; no fix needed."
    if row.critical_rate >= 0.5 and growing:
        return ("Likely active incident: page the owning team, check the latest release, "
                "and give support a ready-made reply.")
    if row.critical_rate >= 0.5:
        return "Trust risk (money, safety or crashes): make it a P1 problem statement with an owner and a guardrail metric."
    if growing:
        return "Growing fast: run a root-cause deep dive this sprint and talk to 5 affected users."
    if row.negative_rate >= 0.6:
        return "Persistent pain point: size it and propose it for next quarter's roadmap."
    return "Monitor; bundle with related work when the area is next touched."


def _trend(row) -> str:
    return f"{row.trend:+.0%}" + ("" if row.trend_significant else " (not significant)")


def build_brief(result: "InsightsResult") -> str:
    df, backlog = result.reviews, result.backlog
    start, end = df["date"].min().date(), df["date"].max().date()
    negative_share = df["sentiment"].eq("negative").mean()
    metrics = result.sentiment_model.metrics

    lines = [
        "# Voice of Customer Insights Brief",
        "",
        f"_Auto-generated by SignalSift from {len(df):,} pieces of feedback, {start} to {end}._",
        "",
        "## TL;DR",
        "",
    ]
    for row in backlog.head(3).itertuples():
        lines.append(f"{row.rank}. **{row.theme}**: {row.reviews:,} reviews, {_pct(row.negative_rate)} negative, "
                     f"{_trend(row)} in the last {result.config.recent_days} days. {_recommendation(row)}")
    lines += ["", f"Overall, {_pct(negative_share)} of feedback is negative."]

    if not result.alerts.empty:
        lines += ["", "## Spike alerts", "",
                  "Weeks where a theme jumped far above its 6-week baseline (z-score >= 3.5).", ""]
        for alert in result.alerts.itertuples():
            segment = top_segment(df, alert.theme)
            where = ""
            if segment and segment["lift"] >= 1.5:
                where = (f" Concentrated in **{segment['segment']}** ({_pct(segment['share_of_theme'])} of this theme "
                         f"vs {_pct(segment['share_of_all'])} of all feedback, {segment['lift']}x lift).")
            lines.append(f"- **{alert.theme}**: first alert week of {alert.week.date()}, {alert.count} reviews vs a "
                         f"baseline of {alert.baseline_mean} (z = {alert.z_score}).{where}")

    lines += ["", "## Prioritised opportunity backlog", "",
              "| Rank | Theme | Reviews | Negative | Trend | Reach (users/mo) | Impact | Confidence | Effort (wks) | Score |",
              "|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for row in backlog.itertuples():
        noise_flag = "" if row.trend_significant else "*"
        lines.append(f"| {row.rank} | {row.theme} | {row.reviews:,} | {_pct(row.negative_rate)} | "
                     f"{row.trend:+.0%}{noise_flag} | {row.reach:,} | {row.impact} | {row.confidence} | "
                     f"{row.effort_weeks:g} | {row.opportunity_score} |")

    lines += ["", r"\* Change vs the previous period is within normal noise (Poisson test, p >= 0.05), "
              "so it does not raise urgency.", "", "## What users are saying", ""]
    for row in backlog.head(3).itertuples():
        examples = df[df["theme"] == row.theme].sort_values("p_negative", ascending=False)["text"].head(2)
        lines.append(f"**{row.theme}**")
        lines += [f"> {text}" for text in examples]
        lines.append("")

    lines += [
        "## Method and confidence",
        "",
        f"- Sentiment: TF-IDF + logistic regression trained on {result.sentiment_trained_on} using star ratings as "
        f"weak labels. Hold-out accuracy {_pct(metrics['accuracy'])}, macro F1 {metrics['macro_f1']}, "
        f"negative recall {_pct(metrics['negative_recall'])}.",
        f"- Themes: TF-IDF -> LSA -> K-Means into {result.theme_model.k} themes, named by their most distinctive terms.",
    ]
    if result.theme_ari is not None:
        lines.append(f"- Theme discovery agrees with the labelled evaluation set at ARI = {result.theme_ari} "
                     "(1.0 = perfect, 0 = random).")
    lines += [
        "- Reach assumes the mix of feedback mirrors the mix of experiences across monthly active users. "
        "Effort is a placeholder until engineering sizes each item.",
        "",
    ]
    return "\n".join(lines)


def write_brief(result: "InsightsResult", path: Path) -> Path:
    path = Path(path)
    path.write_text(build_brief(result), encoding="utf-8")
    return path
